/**
 * Translation shape of the detailed patches (`patches.json` → `patches/<locale>.json`),
 * kept apart from `translate-data.mjs` — which translates as soon as it is
 * loaded — so that it can be tested.
 */
import { IMPLICIT_SUBSECTION } from "./patch-parser.mjs";
import { translateHtml } from "./translation-html.mjs";

/**
 * Label the parser used for the implicit subsection before it wrote English.
 * A `patches.json` generated by an older parser still carries it.
 */
const LEGACY_IMPLICIT_SUBSECTION = "Attributs";

/**
 * Name of a subsection to translate. The implicit subsection (changes listed
 * before any heading) always goes to the translator under the parser's
 * English label, whichever parser generation wrote it: the source language
 * of the patches is English.
 */
export function sectionName(s) {
  if (s.category) return s.name;
  return s.name === IMPLICIT_SUBSECTION || s.name === LEGACY_IMPLICIT_SUBSECTION ? IMPLICIT_SUBSECTION : s.name;
}

/**
 * Detailed patches: adjustment texts, new heroes, titles and free-form HTML
 * of the sections. Left as is: hero and skill names
 * (the game's own, as on the hero pages), epithets (they also name
 * the illustration), before/after values, anchors and links.
 */
export const patchesRebuild = (d, t) =>
  Object.fromEntries(
    Object.entries(d).map(([version, p]) => [
      version,
      {
        ...p,
        toc: p.toc.map((s) => ({ ...s, title: t(s.title) })),
        sections: p.sections.map((s) => ({ ...s, title: t(s.title), html: translateHtml(s.html, t) })),
        newHeroes: p.newHeroes.map((n) => ({
          ...n,
          lore: n.lore.map(t),
          feature: t(n.feature),
          skills: n.skills.map((c) => ({ ...c, role: t(c.role), description: c.description.map(t) })),
        })),
        adjustments: p.adjustments.map((a) => ({
          ...a,
          intro: t(a.intro),
          sections: a.sections.map((s) => ({
            ...s,
            name: s.category ? s.name : t(sectionName(s)),
            category: t(s.category),
            changes: s.changes.map((c) => ("text" in c ? { ...c, text: t(c.text) } : { ...c, label: t(c.label) })),
          })),
        })),
      },
    ]),
  );
